 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def blocks(n, separators):
        result = []
        start = 0
        for pos in separators:
            if pos >= start:
                if pos > start:
                    result.append((start, pos))
                start = pos + 1
        if start < n:
            result.append((start, n))
        return result

    row_blocks = blocks(h, sep_rows)
    col_blocks = blocks(w, sep_cols)
    panels = []
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                panels.append((r0, r1, c0, c1))
    if not panels:
        return [row[:] for row in grid]

    sr0, sr1, sc0, sc1 = panels[0]
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    output = [row[:] for row in grid]
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            if (r1 - r0, c1 - c0) == (sr1 - sr0, sc1 - sc0):
                for dr in range(r1 - r0):
                    for dc in range(c1 - c0):
                        output[r0 + dr][c0 + dc] = pattern[dr][dc]
    return output
